class Solution:
    def deleteDuplicates(self, head: Optional[ListNode]) -> Optional[ListNode]:
        dummy = ListNode(0)
        dummy.next = head
        prev = dummy
        current = head
        while current:
            if current.next and current.val == current.next.val:
                dup_val = current.val
                while current and current.val == dup_val:
                    current = current.next
                prev.next = current
            else:
                prev = current
                current = current.next
        return dummy.next
